@IsTest
private class OwnedAnnotation62Test {
    @SupressWarnings('ExcessiveParameterList')
    private static Integer misspelled() { return 7; }
    @OwnedOpaqueMarker('opaque')
    private static Integer unknown() { return 11; }
    @SuppressWarnings('PMD')
    private static Integer known() { return 13; }
    @OwnedInstanceMarker('opaque')
    private Integer instance() { return 23; }
    @IsTest static void annotationControl() {
        Assert.areEqual(7,misspelled());
        Assert.areEqual(11,unknown());
        Assert.areEqual(13,known());
        Assert.areEqual(23,(new OwnedAnnotation62Test()).instance());
    }
}

